INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('tw-jackrabbit-power-armor', 1, 'Short-Range Rail Gun ("Rabbit Gun")', '1D6 M.D. for a 10 round burst. Silver rounds do 1D6x10 S.D.C. per burst to humanoids, 2D6x10 Hit Points to vampires and other creatures vulnerable to silver.', 1, '2000 feet (610 m)', 'Each burst counts as one melee attack.', '1200 rounds (120 bursts)', NULL, 'Belt-fed, lightweight, snub-nosed rail gun with ammo-can on the back. May fire silver or conventional rounds. Can be hooked to the back of the shoulder or hip when running on all fours. Weight: Gun: 20 lbs (9 kg), Ammo-Drum: 50 lbs (22.5 kg).'),
  ('tw-jackrabbit-power-armor', 2, 'Hand to Hand Combat', '2D4 M.D. kick attacks (most types); 2D6+2 M.D. Karate kick; 4D8 M.D. Leap Kick (counts as two melee attacks), plus 01-60% chance of knocking human-sized opponents in body armor (up to 8 feet/2.4 m tall) off their feet (lose initiative and two melee attacks), 01-30% chance of the same if cyborgs, power armor, robots or superhuman weighing more than 250 lbs (112.5 kg).', 1, NULL, NULL, NULL, NULL, 'Depends on level of training; see Robot (and Power Armor) Combat - Basic and Elite Ground Based Power Armor, pp. 351 and 352 of Rifts Ultimate Edition. All other stats as per Power Armor Combat Basic or Elite.'),
  ('tw-jackrabbit-power-armor', 3, 'Optional Forearm Weapon (1) for the right or left arm', 'Silver Short Sword: 1D6 S.D.C., double damage to undead; Laser: 2D6 M.D. per single blast range 2000 foot (610 m) payload unlimited, tied to the armor''s power supply; Ion Blaster: 4D6 M.D. per single blast range 1000 foot (305 m) payload unlimited, tied to the armor''s power supply', 1, NULL, NULL, NULL, NULL, 'Typically one of the following; costs an extra 15,000-25,000 credits. Note: the Jackrabbit seldom has any other built-in weapons; reduce speed by 10% for each additional weapon should more than one be added.'),
  ('tw-jackrabbit-power-armor', 4, 'Handheld weapons of choice', NULL, 0, NULL, NULL, NULL, NULL, 'The pilot can use any conventional or M.D. weapons and gear he may desire.'),
  ('tw-jackrabbit-power-armor', 5, 'TW Superhuman Speed', NULL, 0, 'Self only', NULL, 'To activate: 10 P.P.E. or 20 I.S.P.. Duration: 5 minutes per activation', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Superhuman Speed (10), Energy Field (10) and Escape (8). Expending 10 P.P.E. boosts Jackrabbit Run max speed to 130 mph (208 km), or 170 mph (272 km) running on all fours; additional +3 to automatic dodge and +2 to roll with impact; double leaping height and distance; negates added fatigue. Applies only to Jackrabbit mode.'),
  ('tw-lonewolf-power-armor', 1, 'Medium Rail Gun ("Vamp-D Gun" short for "destroyer")', '4D6 M.D. for a 20 round burst of Mega-Damage ammo. Silver rounds do 2D4x10 S.D.C. per burst to humanoids, 3D6x10 Hit Points to vampires and other creatures vulnerable to silver.', 1, '2200 feet (670.5 m)', 'Each burst counts as one melee attack.', '2000 rounds (100 bursts)', NULL, 'Belt-fed, snub-nosed, light rail gun with ammo canister on the back. Designed to fire silver or conventional M.D. rounds. (May be substituted with a TW Water Cannon or TW Wood Rail Gun.) Can be hooked to the back, behind a shoulder or on the hip when not in use. Weight: Gun: 40 lbs (18 kg), Ammo Drum: 100 lbs (45 kg).'),
  ('tw-lonewolf-power-armor', 2, 'Wolf''s Bite Forearm Blade (2; one for each arm)', 'Silver Short Sword: 2D4 S.D.C., double damage to undead; Vibro-Sword: 2D4 M.D.', 1, NULL, NULL, NULL, NULL, 'Typically one of the following:'),
  ('tw-lonewolf-power-armor', 3, 'Hand to Hand Combat', NULL, 0, NULL, NULL, NULL, NULL, 'Depends on level of training; see Robot (and Power Armor) Combat - Basic and Elite Ground Based Power Armor, pp. 351 and 352 of Rifts Ultimate Edition. No extra damage line printed.'),
  ('tw-lonewolf-power-armor', 4, 'Handheld weapons of choice', NULL, 0, NULL, NULL, NULL, NULL, 'The pilot can use any conventional or M.D. weapons and gear he may desire.'),
  ('tw-lonewolf-power-armor', 5, 'TW See Invisible', NULL, 0, 'Self only; visual range as per the optic systems of the suit (at least 2000 feet/610 m)', NULL, 'To activate: 4 P.P.E. or 8 I.S.P.. Duration: 6 minutes per activation', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: See the Invisible (4).'),
  ('tw-lonewolf-power-armor', 6, 'TW Force Shield', NULL, 0, 'Self only', NULL, 'To activate: 6 P.P.E. or 12 I.S.P.. Duration: 12 minutes per activation', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Magic Shield (6). Pale white circular field of energy from the right or left forearm (pick one), used like a weightless, medium-sized shield.'),
  ('tw-lonewolf-power-armor', 7, 'TW feature: Mystic Assault', 'Punches 2D6+4 M.D. (restrained punch 3D6 S.D.C.), Energy Bolt 4D6 S.D.C., Electric Bolts 2D6 M.D.', 1, 'Touch or up to 150 feet (45.7 m) for energy blasts', NULL, 'To activate: 13 P.P.E. or 26 I.S.P.. Duration: 5 melee rounds (a minute and 15 seconds)', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Energy Bolt (5), Electric Arc (8) and Fist of Fury (10). Volley of mystic attacks: energy bolt from the eyes, increased Mega-Damage punches, electrical blast from the hands; each blast or punch counts as one melee attack.'),
  ('tw-raging-bull-power-armor', 1, 'Heavy Rail Gun ("Big Puppy")', '1D4x10 M.D. for a 20 round burst of Mega-Damage ammo. Silver rounds do 3D4x10 S.D.C. per burst to humanoids, 4D6x10 Hit Points to vampires and other creatures vulnerable to silver.', 1, '3000 feet (914 m)', 'Each burst counts as one melee attack.', '2000 rounds (100 bursts)', NULL, 'Belt-fed, snub-nosed, heavy rail gun with ammo-canister on the back. Designed to fire silver or conventional M.D. rounds. (May be substituted with a TW Water Cannon or TW Wood Rail Gun.) Can be hooked to the back, behind a shoulder or on the hip when not in use. (Description crosses folio 94 to 95, inside the range.) Weight: Gun: 55 lbs (24.7 kg), Ammo Drum: 200 lbs (90 kg).'),
  ('tw-raging-bull-power-armor', 2, 'Hand to Hand Combat', 'Robot P.S. of 30: 1D6 M.D. from a punch, kick or head butt, 2D6 M.D. from a power punch. When magically increased to Supernatural P.S. of 30: 3D6 M.D. on a full strength punch, kick or head butt, 6D6 M.D. on a power punch.', 1, NULL, NULL, NULL, NULL, 'Depends on level of training; see Robot (and Power Armor) Combat - Basic and Elite Ground Based Power Armor, pp. 351 and 352 of Rifts Ultimate Edition. Plus the following bonuses. All other stats as per Power Armor Combat Basic or Elite.'),
  ('tw-raging-bull-power-armor', 3, 'Handheld weapons of choice', NULL, 0, NULL, NULL, NULL, NULL, 'The pilot can use any conventional or M.D. weapons and gear, although the TW Lightning Mace or a large Vibro-Axe (3D6 M.D.) are commonly suggested or sold with the armor (they fit the ''Minotaur'' image).'),
  ('tw-raging-bull-power-armor', 4, 'TW Superhuman Strength & Endurance', NULL, 0, 'Self only', NULL, 'To activate: 10 P.P.E. or 20 I.S.P.. Duration: 5 minutes (20 melee rounds)', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Superhuman Strength (10). Robotic P.S. becomes Supernatural (M.D. numbers under Hand to Hand Combat); does not fatigue (Supernatural P.E.); can carry 1,500 pounds (675 kg) and lift twice that amount'),
  ('tw-raging-bull-power-armor', 5, 'TW Raging Bull', NULL, 0, 'Self only', NULL, 'To activate: 25 P.P.E. or 50 I.S.P. Once activated it can not be cancelled; may not be reactivated for at least five minutes after the effect wears off.. Duration: One minute (4 melees)', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Armor of Ithan (10), Compulsion (20, self) and Magical-Adrenal Rush (45). Supercharges armor and pilot: Strength again Supernatural, speed +50%, bonuses as listed in the description. PENALTIES: consumed with bloodlust; fights like a bull, never dodging unless the attack is devastating (60 or more M.D.C.); barely aware of anything but fighting; no mercy regardless of alignment; attacks anyone who tries to calm him, friends included; when it ends he is tired and weak and fights with half his usual bonuses, attacks, Spd and skill ability for 1D4 minutes.'),
  ('tw-thunderbird-power-armor', 1, '"Thunderblast" Laser Rifle & Grenade Launcher (1)', 'Laser: 4D6 M.D. Grenade launcher: 2D6 M.D. to a blast radius of 12 feet (3.6 m).', 1, '3000 feet (914 m). Grenade launcher: 1200 feet (365 m).', 'Each laser blast counts as one melee attack.', 'Laser: Effectively unlimited. Grenade Magazine: 16.', NULL, 'High-powered heavy-duty laser rifle cabled into the magic power supply (unlimited firepower); the grenade launcher is close-range. (May be substituted with a TW Water Cannon or any kind of rail gun or other energy rifle.) Can be stowed by hooking it in one of the wings (cannot fire from the wing position). Weight: Gun: 15 lbs (6.7 kg).'),
  ('tw-thunderbird-power-armor', 2, 'Wing Rockets', 'Varies with missile type; typically Armor Piercing (1D4x10 M.D.) or Plasma (1D6x10 M.D.), but may be High Explosive (5D6 M.D.) or special silver fragmentation missiles for fighting vampires (5D6 S.D.C. to everyone within a 15 foot/4.6 m radius, double damage to vampires; 600 credits per silver frag missile).', 1, 'Maximum Effective Range: One mile (1.6 km)', 'One missile at a time or in volleys of two, three, or four; a volley counts as one melee attack regardless of the number of missiles.', 'Total of 20 mini-missiles.', NULL, 'Primary purpose: Anti-Aircraft/Armored Vehicle. Five mini-missiles can be mounted on each wing (20 total), launched by voice command or hidden firing studs in the forearm.'),
  ('tw-thunderbird-power-armor', 3, 'Energy Rifles and other normal weapons', NULL, 0, NULL, NULL, NULL, NULL, 'Energy rifles, grenades, etc. may be used; the less bulky armor allows a side arm, rifle, belts, straps, harness, pouches. Belts and containers can fly off at speeds beyond 100 mph (160 km).'),
  ('tw-thunderbird-power-armor', 4, 'Forearm Blades (8)', 'Mega-Damage Vibro-Blades: 3D4 M.D. per attack; S.D.C. Silver Plated Blades: 3D4 S.D.C. to ordinary mortal opponents, 4D6+4 S.D.C./Hit Point damage to the undead and other creatures vulnerable to silver', 1, NULL, NULL, NULL, NULL, 'Four small dagger-like blades extend from the side of each forearm like fins; used for backhand strikes, forward slicing, or raking as the T-Bird flies past.'),
  ('tw-thunderbird-power-armor', 5, 'Searchlight (1)', NULL, 0, NULL, NULL, NULL, NULL, 'Built into the chest; range 1200 feet (366 m); can angle 30 degrees in any direction. (Folio 98.)'),
  ('tw-thunderbird-power-armor', 6, 'Hand to Hand Combat', NULL, 0, NULL, NULL, NULL, NULL, 'Rather than use a weapon, the pilot can engage in Mega-Damage hand to hand combat. Damage and bonuses as per Power Armor Combat training: Basic or Elite. (Folio 98.)'),
  ('tw-thunderbird-power-armor', 7, 'TW Wing Pack', NULL, 0, NULL, NULL, 'To activate: 15 P.P.E. or 30 I.S.P.. Duration: One hour per activation', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Energy Field (10) and Fly as the Eagle (25). Larger, advanced wing pack: two five-foot (1.5 m) pairs of wings unfold and lock; two gold rods wrapped in copper wire in series with two small P.P.E. batteries; voice and eye-movement control with a hand-control backup on a retractable cord in the forearm. Flies up to 240 mph (380 km), maximum altitude 10,000 feet (3,050 m).'),
  ('tw-thunderbird-power-armor', 8, 'TW Eagle Eye Optics', NULL, 0, NULL, NULL, 'To activate: 10 P.P.E. or 20 I.S.P. will power the entire system; any of the systems may be used in any combination. Duration: 10 minutes per activation', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Eyes of the Wolf (25), See the Invisible (4), and Light Target (6).'),
  ('tw-thunderbird-power-armor', 9, 'TW Thunder Bolt', '1D6x10 M.D. or 2D6x10 M.D.', 1, 'Line of sight; up to 6000 feet (1829 m) in a straight line, altitude does not count', NULL, 'To activate: Lightning Attack header: 10 P.P.E. or 20 I.S.P.; then (folio 97) ''Each blast costs only 8 P.P.E. or 16 I.S.P. to do 1D6x10 damage (double the P.P.E./I.S.P. cost to do double damage)''. Duration: Instant', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Call Lightning (15) and Electric Arc (8). Long-range magical artillery: true lightning bolts; requires open sky, can NOT be used indoors or where the target has overhead protection. Lightning Attack: 1D6x10 M.D. or 2D6x10 M.D. (the latter counts as two melee attacks and costs extra P.P.E.). Electric Arc Attack alternative: 2D6 M.D. Electric Arc up to 300 feet (91.5 m) at 1 P.P.E. (or 2 I.S.P.). Half cost if the pilot drains internal energy: speed -5% per blast (30 minutes to recover; two hours if below half; cannot go below 10%).'),
  ('tw-guardian-angel-power-armor', 1, 'TW Healing Touch', NULL, 0, 'Other by touch', NULL, 'To activate: 6 P.P.E. or 12 I.S.P. per healing touch. Duration: Instant', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Cleanse (6), Greater Healing (25), and Negate Poison (5). Gold and silver wiring runs to gold plates on the gauntlet fingertips; laying hands on a wounded person heals even through environmental armor. Heals 3D6+10 S.D.C. and 2D6+6 Hit Points (or 1D6 M.D.C. to natural Mega-Damage creatures), cleans and sterilizes wounds, neutralizes poison and drugs (stops damage and erases effects but does not restore lost H.P. or S.D.C.).'),
  ('tw-guardian-angel-power-armor', 2, 'TW Combating the Forces of Evil', NULL, 0, 'Self', NULL, 'To activate: 6 P.P.E. or 12 I.S.P.. Duration: 8 minutes per activation', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Globe of Daylight (2) Sense Evil (2), and Turn Dead (6). Sense Evil within a 100 foot (printed ''301.5 m'') radius, turn (drive away) 3D6+12 animated dead, or drive away 2D6+6 Wild Vampires or hold at bay 1D6+1 Secondary Vampires (cannot come within 30 feet/9.1 m); sensing shows whether evil is present, whether vampires or a great evil, not the source.'),
  ('tw-guardian-angel-power-armor', 3, 'TW Angelic Wings', NULL, 0, 'The wings affect the wearer only; the aura reaches 60 feet (18.3 m)', NULL, 'To activate: 12 P.P.E. or 24 I.S.P.. Duration: 20 minutes per activation', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Winged Flight (35), Float in Air (5), Fly as the Eagle (25), and Charismatic Aura (10). Glowing ectoplasmic wings of pale blue light formed from two reservoirs on the shoulder blades. Allies within 60 feet (18.3 m) feel calm and trust; awestruck enemies who press an attack on the Guardian Angel have no initiative, -1 attack per melee round and half their bonuses to strike until it attacks them. Flying speed 50 mph (80 km), and it can hover. Awe Factor 14 or 16 with the wings visible, 10 without. Saving throw vs Awe: 14 for most enemies; 16 or higher for those in need of healing or rescue, who believe in angels or are glad to see the character.'),
  ('tw-guardian-angel-power-armor', 4, 'TW Magic Force Field', NULL, 0, 'Self and those held in the Angel''s arms', NULL, 'To activate: 12 P.P.E. or 24 I.S.P.. Duration: 10 minutes per activation, or until the M.D.C. is depleted', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Spell effects: Armor of Ithan (10) and Energy Field (10). Protects the armor and up to two people held in its arms; damage comes off the field first, and a new field can be raised one melee round after the last one vanished. M.D.C.: 80.'),
  ('tw-grinning-gunship', 1, 'Multi-Purpose Rail Gun', 'Conventional rounds do 1D6x10 M.D. from a 40 round burst (no damage to the undead), while silver rounds do 4D6 M.D. but 2D4x10 Hit Points to vampires. Wooden rounds do 1D4 M.D. but 3D4x10 Hit Points to vampires.', 1, '4,000 feet (1,219 m)', 'Each burst counts as one melee attack; can only fire bursts.', '4000 round drum feed for a total of 100 bursts. Reloading takes the proper equipment and an Operator or Robot Pilot and 1D6+5 minutes (half the time from a trained field crew).', NULL, 'Fired by the pilot Primary purpose: Anti-Power Armor/Aircraft & Air to Ground. A conventional rail gun can be loaded with standard or silver rounds, or a TW rail gun that fires wooden rounds or a water cannon may be substituted. Intro text: front-mounted heavy rail gun.'),
  ('tw-grinning-gunship', 2, 'Mini-Missile Launcher', 'As per missile, typically fragmentation (4D6 M.D. to a 12 foot/3.6 m radius).', 1, NULL, 'Volleys of 2, 4, or 8.', '48 mini-missiles', NULL, 'Operated by the co-pilot Primary purpose: Anti-Infantry, Anti-Power Armor & Air to Ground.'),
  ('tw-grinning-gunship', 3, 'Optional Door Gunner', NULL, 0, NULL, NULL, NULL, NULL, 'The side door may be opened and an additional gunner stationed there, tied in with a harness. Typical weaponry is a heavy energy rifle, light rail gun, or TW Water Cannon.'),
  ('tw-grinning-gunship', 4, 'TW feature: Magical Force Field', NULL, 0, NULL, NULL, 'To activate: 20 P.P.E. or 40 I.S.P. Duration: 10 minutes per activation or until M.D.C. is depleted, whichever comes first.', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Built into the helicopter to supplement its relatively thin armor; adds damage capacity and helps keep down repair expenses. The mystic shield prevents those inside the chopper from shooting out. M.D.C.: 200.'),
  ('tw-kamikaze-fighter', 1, 'Medium TK Machine-gun', '1D4x10 M.D. per burst (2 Lasers: 2D6 M.D. per single shot, 4D6 M.D. per dual blast).', 1, '2000 feet (610 m)', 'Each burst counts as one melee attack.', 'Effectively unlimited with a TW generator, 30 bursts with a battery, and an additional burst can be magically created by the pilot spending 7 P.P.E. or 14 I.S.P.', NULL, 'Primary purpose: Anti-Aircraft and Air to Ground. Used primarily for strafing. Nose-mounted per intro text. The parenthetical 2-laser figures are the 4500B variant.'),
  ('tw-kamikaze-fighter', 2, 'Missile Launcher', 'As per missile style; typically Fragmentation: 5D6 M.D. or High Explosive: 5D6 M.D. (The 4500B will launch Armor Piercing: 1D4x10 M.D. or Plasma: 1D6x10 M.D.)', 1, NULL, '2 or 4 at a time in a single volley. (In the 4500B, 2, 4 or the entire payload may be launched in a single volley.)', '8 mini-missiles or 4 short-range missiles. (14 mini-missiles, or 6 short-range missiles.)', NULL, 'Primary purpose: Anti-Aircraft & Air to Ground. Capable of using conventional or TW mini-missiles or short-range missiles. The 4500B has a greater payload and volley capacity.'),
  ('tw-kamikaze-fighter', 3, 'Additional Systems: TW-VTOL', NULL, 0, 'Maximum height 100 feet (30.5 m) for takeoff or landing assist', NULL, NULL, NULL, 'TW-VTOL (vertical take-off and landing) system created using Levitation as part of the combination of creation spells. Activated with 6 P.P.E. from the pilot to raise the aircraft to a maximum height of 100 feet (30.5 m), or ease the craft to the ground from a maximum of 100 feet (30.5 m) up. Landings are tricky; using the flaps and easing in at speeds under 50 mph (80 km) is manageable for an experienced pilot. VTOL landings are -15% on the piloting roll.'),
  ('tw-kamikaze-fighter', 4, 'Bombs (4500B bomber variant, none produced)', '1D4x10 M.D. per bomb to a 20 foot/6.1 m diameter of destruction', 1, NULL, 'Dropped in clusters of 2, 4, 8, 16 or all 24 bombs', '24 bombs', NULL, 'Unguided explosives dropped from the belly. Carrying bombs attached to the underbelly reduces maximum speed by 30%. Printed as a parenthetical Note, 4500B only.'),
  ('tw-whirlybird-personal-helicopter', 1, 'Light Multi-Purpose Rail Gun (1)', 'Conventional rounds do 5D6 M.D. per burst of 30 rounds, while silver rounds do 2D6 M.D. or 1D4x10 Hit Points to vampires. Wooden rounds do 1D4 M.D. or 2D4x10 Hit Points to vampires.', 1, '3,000 feet (914 m)', 'Each burst counts as a melee attack; can only fire bursts.', '900 rounds of conventional or silver ammo for a total of 30 bursts.', NULL, 'Primary purpose: Anti-Armor and Air to Ground Attacks. TW rail gun firing wooden rounds or a TW Water Cannon may be substituted (but they can''t fire conventional rounds). Usually mounted on the undercarriage, or directly beneath the pilot.'),
  ('tw-whirlybird-personal-helicopter', 2, 'Light Double-Barreled Laser (1)', 'Single Laser blast: 2D6 M.D. or a simultaneous dual blast at the same target: 4D6 M.D. blast.', 1, '2,000 feet (610 m)', 'Each single or double blast counts as one melee attack.', 'Effectively unlimited if wired to a TW generator, 50 if hooked to a TW battery only (each 2D6 M.D. blast draining one P.P.E. point from it). May be supplemented with the P.P.E. of the pilot, as usual.', NULL, 'Primary purpose: Anti-Personnel, Air to Ground and Defense. A conventional laser system wired to a TW power supply.');

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('tw-whirlybird-personal-helicopter', 3, 'Missile Launcher', 'As per missile; may use conventional warheads or TW types.', 1, NULL, 'Up to the entire payload may be fired in one volley.', '6 mini-missiles or 3 short-range missiles.', NULL, 'Primary purpose: Assault, Anti-Aircraft and Defense. Small missile launcher mounted on a weapon arm, firing mini-missiles or short-range missiles; used against enemy infantry or fortified positions.'),
  ('tw-whirlybird-personal-helicopter', 4, 'TW Fire Blaster', '6D6 M.D.', 1, '1,600 feet (488 m)', 'Each blast counts as one melee attack.', 'Effectively unlimited if wired to a TW generator, 15 if hooked to a TW battery only (each blast drains 5 P.P.E. from the main battery). May be supplemented with the P.P.E. of the pilot, as usual.', NULL, 'Primary purpose: Assault and Defense. Bolts of magical plasma from forward-fixed cannons mounted beside or underneath the cockpit.'),
  ('tw-whirlybird-personal-helicopter', 5, 'Undead Scorcher', '5D6 Hit Points per blast to vampires; none to humans or most other mortal beings or S.D.C. objects.', 0, '600 feet (183 km) [printed km after 183, as printed]', 'Each blast counts as one melee attack.', 'Effectively unlimited if wired to a TW generator, 12 if hooked to a TW battery only (each blast drains 4 P.P.E. from the main battery). May be supplemented with the P.P.E. of the pilot, as usual. Note: So far this weapon has not been successfully turned into a man portable rifle.', NULL, 'Primary purpose: Vampire Slayer. Resembles a heavy rifle or rail gun with a thick barrel; fires a beam of light that is a stream of daylight (a la the Globe of Daylight spell).'),
  ('tw-whirlybird-personal-helicopter', 6, 'Communications Package', NULL, 0, 'Radio/video 500 miles (800 km); radar 10 miles (16 km)', NULL, NULL, 'Communications decoder: +20% to Cryptography skill (through Tongues spell).', 'P.P.E.-driven with a mundane backup power system. Printed list: 20 scrambled frequencies; radio and video transmitters and receivers, range of 500 miles (800 km); audio and video recording capability; video camera with 100x zoom; still camera capable of taking 1200 digital pictures; a communications decoder, +20% to Cryptography skill (through Tongues spell); medium-range radar, range of 10 miles (16 km), capable of tracking 20 targets simultaneously.'),
  ('tw-whirlybird-personal-helicopter', 7, 'TW Carpet of Adhesion Skids', NULL, 0, NULL, NULL, NULL, NULL, 'Replaces the landing wheels with flat landing feet that adhere securely to a surface (vehicle top or landing pad); doubles as an anti-theft device, sticking until the owner flips a hidden switch or magically removes the adhesion. Stunt landing (sticking to the side of larger vehicles, buildings, a bridge, etc., piloting at nearly 90 degrees): -35% penalty if the object is stationary, -50% if a large moving body; a failed roll means the Whirlybird crashes into the object and falls, almost certainly wrecked. No cost, P.P.E. or duration printed.'),
  ('tw-whirlybird-personal-helicopter', 8, 'Enhanced Carrying Capacity', NULL, 0, NULL, NULL, NULL, NULL, 'At the sacrifice of a weapon system and through some redistribution of equipment, the Whirlybird can carry one passenger or an additional 50 cubic feet (1.4 cubic meters) of cargo. Reduce top speed by 20% due to less-than-ideal weight distribution.'),
  ('tw-sandstorm-hover-craft', 1, 'Mounted Shotgun', 'Explosive rounds do 3D6 M.D. per single blast or 6D6 M.D. per double-barreled blast. Silver rounds do 4D6 Hit Point damage per single blast or 1D4x10 Hit Points per double blast to vampires.', 1, 'Effective Range: Shotgun: 300 feet (91.5 m), longer range for other types of weapons (2000 feet/610 m for a laser).', 'Each blast counts as one melee attack for the gunner.', '6 individual shots, or 3 double blasts.', NULL, 'Primary purpose: Assault and Defense. Double-barreled; explosive M.D. or silver rounds. A Big Bore shotgun, TW Water Cannon or conventional laser can be substituted. Swivel mount at the co-pilot/gunner''s station; fires forward or up to 90 degrees right, with a 30 degree vertical arc of fire.'),
  ('tw-sandstorm-hover-craft', 2, 'Mini-Missile Launcher', 'Varies with missile type.', 1, NULL, 'One at a time, or volley of 2 or 4.', '8 mini-missiles.', NULL, 'Primary purpose: Anti-Personnel/Anti-Vampire. On top of the vehicle, mounted on the roll bar; missiles easily exchanged. Wood or silver fragmentation missiles or conventional warheads.'),
  ('tw-sandstorm-hover-craft', 3, 'Headlight', 'None as a light for illumination, but with the cross pattern it does 4D6 Hit Points to vampires struck by the light and image.', 0, '300 feet (91.5 m)', NULL, 'Effectively unlimited.', NULL, 'Primary purpose: Anti-Vampire. High-powered headlight rigged to cast the shadow of a cross.'),
  ('tw-sandstorm-hover-craft', 4, 'Dust Cloud/Sandstorm', NULL, 0, 'Plume 100 foot (30.5 m) long and 30 foot (9.1 m) wide, 50 foot (15.2 m) tall', NULL, NULL, NULL, 'Dust and sand from the hover jets cloak whoever is behind the craft. Those in the cloud cannot be seen from outside but drive blind: -60% piloting penalty when relying on sight alone and -10 to strike, parry, dodge, etc. ALL driving inside must be via instrumentation (-20% penalties on the piloting skill) or luck.'),
  ('tw-sandstorm-hover-craft', 5, 'Other Weapon Systems', NULL, 0, NULL, NULL, NULL, NULL, 'The buyer can opt for up to two small weapon systems, one on each side, operated by additional gunners. Typical additions include shotgun, rail gun, light to medium laser, TW water cannon and/or another cross and light.'),
  ('tw-sandstorm-hover-craft', 6, 'TW feature: Magic Force Field', NULL, 0, NULL, NULL, 'To activate: 10 P.P.E. or 20 I.S.P. Duration: 10 minutes per activation or until depleted, whichever comes first.', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Standard because of the open frame. Activating it precludes the use of any weapons in the possession of passengers as well as built-in vehicular weapon systems. Purchasing without the force field reduces the cost by one million credits. M.D.C.: 80.'),
  ('tw-cliff-rider-personal-atv', 1, 'TW feature: Cliff Rider', NULL, 0, NULL, NULL, 'To activate: 15 P.P.E. or 30 I.S.P. for one hour of wall climbing capable drive time. Duration: One hour of wall climbing capable drive time per activation', NULL, 'Techno-Wizard feature, not a weapon unless it says so. Drive up and down steep angles, sheer walls, and inverted surfaces like ceilings or under a bridge, as long as the surface can bear the weight of the vehicle, rider and gear. Gravity still applies: rider and cargo must be strapped down. The vehicle has cargo tie-downs, a seatbelt, shoulder straps and stirrups for the driver; passengers have no built-in supports.'),
  ('tw-cliff-rider-personal-atv', 2, 'TW Force Field (optional add-on)', NULL, 0, NULL, NULL, NULL, NULL, 'Techno-Wizard feature, not a weapon unless it says so. Provides 80 M.D.C. and protects drive and vehicle; extra one million credits. No activation cost printed. M.D.C.: 80.'),
  ('tw-rover-dune-buggy', 1, 'Forward Swivel Gun', 'Light rail gun: 3D6 M.D. per 20 round burst; or single barrel laser: 2D6 M.D.', 1, 'Light rail gun 3000 foot/914 m range; laser 2000 foot/610 range (printed without m)', NULL, 'Light rail gun 800 round payload for 40 bursts; laser unlimited payload if tied into a TW generator.', NULL, 'Handle mounted between the driver''s and front passenger''s seats swivels side to side and controls a conventional M.D. weapon; either driver or front passenger can operate it, or it may be locked forward. No Primary Purpose line printed.'),
  ('tw-rover-dune-buggy', 2, 'Concealed Headlights (2)', NULL, 0, NULL, NULL, NULL, NULL, 'A pair of high-powered headlights rise up above the forward gun. A second pair can be mounted on the roll bar facing the front or the rear.'),
  ('tw-sand-ranger-combat-truck', 1, 'TW Dual Brimstone Plasma Cannons', '4D6 M.D. per single blast or 6D6+14 per twin, simultaneous blasts at the same target.', 1, '1,200 feet (366 km) [printed km]', 'Each single or double blast counts as one melee attack.', 'Unlimited with a TW generator, 40 blasts with a battery, each individual blast drains 2 P.P.E. from the battery. Or one blast can be fired for every 8 P.P.E. (or 16 I.S.P.) pumped into the TW weapon by someone inside the vehicle.', NULL, 'Primary purpose: Assault & Defense. Bolts of magical fire from forward-fixed units mounted above the front wheel-wells and below the headlights; fired by the driver via steering wheel controls or by a shotgun-seat gunner via a dashboard control.'),
  ('tw-sand-ranger-combat-truck', 2, 'Rear, Truck Bed Gun Turret', 'Varies with weapon type, but generally does 6D6 M.D., 1D4x10 M.D. or 1D6x10 M.D., or similar Hit Point damage for anti-vampire weapons.', 1, 'Varies with weapon; 2,000-4,000 feet (610 to 1219 m).', 'Each blast counts as one melee attack.', '50-100 bursts of conventional or silver ammunition, unlimited for energy weapons tied into a TW generator, 15-30 for those tied into a P.P.E. Battery (40-60 if the weapon has its own battery).', NULL, 'Primary purpose: Assault & Defense. Heavy weapon (typically heavy laser, laser pulse cannon, plasma cannon, rail gun, or TW Water Cannon) on a built-in ball unit atop a removable stand mid-truck; 360 degree horizontal arc, 45 degrees up and down; standing or seated mounts. The standard rail gun may be loaded with normal or silver rounds, or substituted with a water cannon, energy rifle, or other weapon.'),
  ('tw-sand-ranger-combat-truck', 3, 'Headlights (4)', NULL, 0, NULL, NULL, NULL, NULL, 'Two pairs of high-powered headlights are standard. A second pair of lights can be mounted on top of the truck facing the front.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 12 machines are in' AS assertion, count(*) AS got, 12 AS want
  FROM vehicles WHERE slug IN ('tw-jackrabbit-power-armor', 'tw-lonewolf-power-armor', 'tw-raging-bull-power-armor', 'tw-thunderbird-power-armor', 'tw-guardian-angel-power-armor', 'tw-grinning-gunship', 'tw-kamikaze-fighter', 'tw-whirlybird-personal-helicopter', 'tw-sandstorm-hover-craft', 'tw-cliff-rider-personal-atv', 'tw-rover-dune-buggy', 'tw-sand-ranger-combat-truck');
SELECT 'their 70 locations are in' AS assertion, count(*) AS got, 70 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('tw-jackrabbit-power-armor', 'tw-lonewolf-power-armor', 'tw-raging-bull-power-armor', 'tw-thunderbird-power-armor', 'tw-guardian-angel-power-armor', 'tw-grinning-gunship', 'tw-kamikaze-fighter', 'tw-whirlybird-personal-helicopter', 'tw-sandstorm-hover-craft', 'tw-cliff-rider-personal-atv', 'tw-rover-dune-buggy', 'tw-sand-ranger-combat-truck');
SELECT 'their 59 weapon entries are in' AS assertion, count(*) AS got, 59 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('tw-jackrabbit-power-armor', 'tw-lonewolf-power-armor', 'tw-raging-bull-power-armor', 'tw-thunderbird-power-armor', 'tw-guardian-angel-power-armor', 'tw-grinning-gunship', 'tw-kamikaze-fighter', 'tw-whirlybird-personal-helicopter', 'tw-sandstorm-hover-craft', 'tw-cliff-rider-personal-atv', 'tw-rover-dune-buggy', 'tw-sand-ranger-combat-truck');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('tw-jackrabbit-power-armor', 'tw-lonewolf-power-armor', 'tw-raging-bull-power-armor', 'tw-thunderbird-power-armor', 'tw-guardian-angel-power-armor', 'tw-grinning-gunship', 'tw-kamikaze-fighter', 'tw-whirlybird-personal-helicopter', 'tw-sandstorm-hover-craft', 'tw-cliff-rider-personal-atv', 'tw-rover-dune-buggy', 'tw-sand-ranger-combat-truck') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~245-arzno-vehicles.sql');
